def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "grab_statue": And([
            Not(self.newspaper_moved),  # Newspaper not moved aside
            self.statue_to_left_of_newspaper,
            Not(self.gripper_can_detect_newspaper)
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
